import type { NextConfig } from 'next';

const nextConfig: NextConfig = {};

export default nextConfig;

import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';

export type BookStatus = 'reading' | 'finished';

export interface Book {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: BookStatus;
  createdAt: string;
  finishedAt?: string | null;
}

const DATA_FILE_PATH = path.join(process.cwd(), 'books.json');

async function ensureFileExists(): Promise<void> {
  try {
    await fs.access(DATA_FILE_PATH);
  } catch {
    await fs.writeFile(DATA_FILE_PATH, JSON.stringify([], null, 2), 'utf-8');
  }
}

export async function getBooks(): Promise<Book[]> {
  await ensureFileExists();
  try {
    const raw = await fs.readFile(DATA_FILE_PATH, 'utf-8');
    if (!raw.trim()) {
      return [];
    }
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch (error) {
    console.error('Failed to read books from storage:', error);
    return [];
  }
}

export async function saveBooks(books: Book[]): Promise<void> {
  await ensureFileExists();
  await fs.writeFile(DATA_FILE_PATH, JSON.stringify(books, null, 2), 'utf-8');
}

export async function getBookById(id: string): Promise<Book | null> {
  const books = await getBooks();
  return books.find((book) => book.id === id) || null;
}

export async function addBook(input: {
  title: string;
  author: string;
  notes?: string;
  status?: BookStatus;
}): Promise<Book> {
  const books = await getBooks();
  const newBook: Book = {
    id: crypto.randomUUID(),
    title: input.title.trim(),
    author: input.author.trim(),
    notes: (input.notes || '').trim(),
    status: input.status || 'reading',
    createdAt: new Date().toISOString(),
    finishedAt: input.status === 'finished' ? new Date().toISOString() : null,
  };

  books.unshift(newBook);
  await saveBooks(books);
  return newBook;
}

export async function markBookAsFinished(id: string): Promise<Book | null> {
  const books = await getBooks();
  const bookIndex = books.findIndex((book) => book.id === id);
  if (bookIndex === -1) {
    return null;
  }

  books[bookIndex] = {
    ...books[bookIndex],
    status: 'finished',
    finishedAt: new Date().toISOString(),
  };

  await saveBooks(books);
  return books[bookIndex];
}

export async function updateBookStatus(id: string, status: BookStatus): Promise<Book | null> {
  const books = await getBooks();
  const bookIndex = books.findIndex((book) => book.id === id);
  if (bookIndex === -1) {
    return null;
  }

  books[bookIndex] = {
    ...books[bookIndex],
    status,
    finishedAt: status === 'finished' ? (books[bookIndex].finishedAt || new Date().toISOString()) : null,
  };

  await saveBooks(books);
  return books[bookIndex];
}

