import { NextResponse } from 'next/server';
import { getBooks, addBook } from '@/lib/books';

export async function GET() {
  try {
    const books = await getBooks();
    return NextResponse.json(books);
  } catch (error) {
    return NextResponse.json({ error: 'Failed to retrieve books' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { title, author, notes, status } = body;

    if (!title || typeof title !== 'string' || !title.trim()) {
      return NextResponse.json({ error: 'Title is required' }, { status: 400 });
    }

    if (!author || typeof author !== 'string' || !author.trim()) {
      return NextResponse.json({ error: 'Author is required' }, { status: 400 });
    }

    const book = await addBook({
      title,
      author,
      notes: typeof notes === 'string' ? notes : '',
      status: status === 'finished' ? 'finished' : 'reading',
    });

    return NextResponse.json(book, { status: 201 });
  } catch (error) {
    return NextResponse.json({ error: 'Failed to add book' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { getBookById, markBookAsFinished, updateBookStatus } from '@/lib/books';

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const book = await getBookById(id);

    if (!book) {
      return NextResponse.json({ error: 'Book not found' }, { status: 404 });
    }

    return NextResponse.json(book);
  } catch (error) {
    return NextResponse.json({ error: 'Failed to retrieve book' }, { status: 500 });
  }
}

export async function PATCH(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const body = await request.json();

    let updatedBook;
    if (body.status === 'finished') {
      updatedBook = await markBookAsFinished(id);
    } else if (body.status === 'reading') {
      updatedBook = await updateBookStatus(id, 'reading');
    } else {
      return NextResponse.json({ error: 'Invalid status' }, { status: 400 });
    }

    if (!updatedBook) {
      return NextResponse.json({ error: 'Book not found' }, { status: 404 });
    }

    return NextResponse.json(updatedBook);
  } catch (error) {
    return NextResponse.json({ error: 'Failed to update book' }, { status: 500 });
  }
}

