'use client';

import { useState } from 'react';
import Link from 'next/link';
import type { Book } from '@/lib/books';

interface BookTrackerProps {
  initialBooks: Book[];
}

export default function BookTracker({ initialBooks }: BookTrackerProps) {
  const [books, setBooks] = useState<Book[]>(initialBooks);
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [notes, setNotes] = useState('');
  const [status, setStatus] = useState<'reading' | 'finished'>('reading');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  const currentlyReading = books.filter((b) => b.status === 'reading');
  const finishedBooks = books.filter((b) => b.status === 'finished');

  async function handleAddBook(e: React.FormEvent) {
    e.preventDefault();
    if (!title.trim() || !author.trim()) {
      setErrorMessage('Please provide both title and author.');
      return;
    }

    setIsSubmitting(true);
    setErrorMessage('');

    try {
      const res = await fetch('/api/books', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title,
          author,
          notes,
          status,
        }),
      });

      if (!res.ok) {
        throw new Error('Failed to create book');
      }

      const newBook: Book = await res.json();
      setBooks((prev) => [newBook, ...prev]);
      setTitle('');
      setAuthor('');
      setNotes('');
      setStatus('reading');
    } catch (err) {
      setErrorMessage('Failed to add book. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  }

  async function handleMarkFinished(e: React.MouseEvent, id: string) {
    e.preventDefault();
    e.stopPropagation();

    try {
      const res = await fetch(`/api/books/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'finished' }),
      });

      if (!res.ok) {
        throw new Error('Failed to update book status');
      }

      const updatedBook: Book = await res.json();
      setBooks((prev) =>
        prev.map((book) => (book.id === id ? updatedBook : book))
      );
    } catch (err) {
      console.error(err);
    }
  }

  return (
    <div>
      {/* Add Book Section */}
      <section className="card">
        <h2 className="section-title">Add a Book</h2>
        <form onSubmit={handleAddBook}>
          {errorMessage && (
            <p style={{ color: '#dc2626', fontSize: '0.9rem', marginBottom: '0.75rem' }}>
              {errorMessage}
            </p>
          )}
          <div className="form-row">
            <div className="form-group">
              <label htmlFor="title">Title *</label>
              <input
                id="title"
                className="form-input"
                type="text"
                placeholder="e.g. Project Hail Mary"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="author">Author *</label>
              <input
                id="author"
                className="form-input"
                type="text"
                placeholder="e.g. Andy Weir"
                value={author}
                onChange={(e) => setAuthor(e.target.value)}
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label htmlFor="notes">Notes</label>
            <textarea
              id="notes"
              className="form-textarea"
              placeholder="Your thoughts, quotes, reflections..."
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
            />
          </div>

          <div className="form-group" style={{ display: 'flex', gap: '1.5rem', alignItems: 'center' }}>
            <label style={{ margin: 0 }}>Initial Status:</label>
            <label style={{ fontWeight: 'normal', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.35rem' }}>
              <input
                type="radio"
                name="status"
                value="reading"
                checked={status === 'reading'}
                onChange={() => setStatus('reading')}
              />
              Currently Reading
            </label>
            <label style={{ fontWeight: 'normal', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.35rem' }}>
              <input
                type="radio"
                name="status"
                value="finished"
                checked={status === 'finished'}
                onChange={() => setStatus('finished')}
              />
              Finished
            </label>
          </div>

          <button
            type="submit"
            className="btn btn-primary"
            disabled={isSubmitting}
          >
            {isSubmitting ? 'Adding...' : 'Add Book'}
          </button>
        </form>
      </section>

      {/* Currently Reading Section */}
      <section style={{ marginBottom: '2.5rem' }}>
        <h2 className="section-title">
          <span>Currently Reading</span>
          <span className="badge">{currentlyReading.length}</span>
        </h2>

        {currentlyReading.length === 0 ? (
          <p className="empty-state">Not currently reading any books. Add one above!</p>
        ) : (
          <div className="book-list">
