'use client';

import { useState } from 'react';

interface BookDetailActionsProps {
  bookId: string;
  initialStatus: 'reading' | 'finished';
}

export default function BookDetailActions({
  bookId,
  initialStatus,
}: BookDetailActionsProps) {
  const [status, setStatus] = useState<'reading' | 'finished'>(initialStatus);
  const [copied, setCopied] = useState(false);
  const [loading, setLoading] = useState(false);

  async function handleMarkFinished() {
    setLoading(true);
    try {
      const res = await fetch(`/api/books/${bookId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'finished' }),
      });
      if (res.ok) {
        setStatus('finished');
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }

  function handleCopyShareLink() {
    if (typeof window !== 'undefined') {
      navigator.clipboard.writeText(window.location.href);
      setCopied(true);
      setTimeout(() => setCopied(false), 2500);
    }
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', marginTop: '1.5rem' }}>
      <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center' }}>
        {status === 'reading' && (
          <button
            type="button"
            className="btn btn-primary"
            onClick={handleMarkFinished}
            disabled={loading}
          >
            {loading ? 'Marking...' : '✓ Mark as finished'}
          </button>
        )}
        <button
          type="button"
          className="btn btn-secondary"
          onClick={handleCopyShareLink}
        >
          🔗 {copied ? 'Link copied to clipboard!' : 'Copy link to share'}
        </button>
      </div>
    </div>
  );
}

import { notFound } from 'next/navigation';
import Link from 'next/link';
import type { Metadata } from 'next';
import { getBookById } from '@/lib/books';
import BookDetailActions from './BookDetailActions';

export const dynamic = 'force-dynamic';

interface PageProps {
  params: Promise<{ id: string }>;
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { id } = await params;
  const book = await getBookById(id);

  if (!book) {
    return {
      title: 'Book Not Found',
    };
  }

  return {
    title: `${book.title} by ${book.author} | Book Tracker`,
    description: book.notes || `Book details for ${book.title}`,
  };
}

export default async function BookDetailPage({ params }: PageProps) {
  const { id } = await params;
  const book = await getBookById(id);

  if (!book) {
    notFound();
  }

  return (
    <div>
      <Link href="/" className="back-link">
        ← Back to books
      </Link>

      <article className="card">
        <div className="book-detail-header">
          <div>
            <h1 className="book-detail-title">{book.title}</h1>
            <p className="book-detail-author">by {book.author}</p>
          </div>
          <div>
            <span
              className={`badge ${
                book.status === 'finished' ? 'badge-finished' : ''
              }`}
            >
              {book.status === 'finished' ? 'Finished' : 'Currently Reading'}
            </span>
          </div>
        </div>

        <div className="notes-section">
          <h2 className="notes-heading">My Notes</h2>
          {book.notes && book.notes.trim() ? (
            <div className="notes-content">{book.notes}</div>
          ) : (
            <p className="empty-state" style={{ padding: '0.5rem 0' }}>
              No notes added for this book.
            </p>
          )}
        </div>

        <BookDetailActions
          bookId={book.id}
          initialStatus={book.status}
        />
      </article>
    </div>
  );
}

