import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs/promises';
import path from 'node:path';
import {
  getBooks,
  saveBooks,
  addBook,
  markBookAsFinished,
  getBookById,
  type Book,
} from './src/lib/books';

const TEST_FILE_PATH = path.join(process.cwd(), 'books.json');

describe('Book Tracker storage', () => {
  let originalData: string | null = null;

  beforeEach(async () => {
    try {
      originalData = await fs.readFile(TEST_FILE_PATH, 'utf-8');
    } catch {
      originalData = null;
    }
    await fs.writeFile(TEST_FILE_PATH, '[]', 'utf-8');
  });

  afterEach(async () => {
    if (originalData !== null) {
      await fs.writeFile(TEST_FILE_PATH, originalData, 'utf-8');
    } else {
      try {
        await fs.unlink(TEST_FILE_PATH);
      } catch {}
    }
  });

  it('starts with empty list if no books exist', async () => {
    const books = await getBooks();
    expect(books).toEqual([]);
  });

  it('adds a new book reading by default', async () => {
    const book = await addBook({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'Classic sci-fi novel about Arrakis.',
    });

    expect(book.id).toBeDefined();
    expect(book.title).toBe('Dune');
    expect(book.author).toBe('Frank Herbert');
    expect(book.notes).toBe('Classic sci-fi novel about Arrakis.');
    expect(book.status).toBe('reading');

    const stored = await getBooks();
    expect(stored.length).toBe(1);
    expect(stored[0].id).toBe(book.id);
  });

  it('marks a book as finished', async () => {
    const book = await addBook({
      title: 'The Hobbit',
      author: 'J.R.R. Tolkien',
    });

    expect(book.status).toBe('reading');

    const updated = await markBookAsFinished(book.id);
    expect(updated?.status).toBe('finished');
    expect(updated?.finishedAt).toBeTruthy();

    const fetched = await getBookById(book.id);
    expect(fetched?.status).toBe('finished');
  });

  it('retrieves a book by id for single book viewing', async () => {
    const book = await addBook({
      title: '1984',
      author: 'George Orwell',
      notes: 'Thought-provoking dystopian fiction.',
    });

    const found = await getBookById(book.id);
    expect(found).not.toBeNull();
    expect(found?.title).toBe('1984');
    expect(found?.author).toBe('George Orwell');
    expect(found?.notes).toBe('Thought-provoking dystopian fiction.');
  });
});

